/** Native block placement, merchant packets/slots, XP use and real on-disk reconnect. */
public final class EnchanterClientGameTest implements FabricClientGameTest {
    private static void check(boolean v,String m){DisenchantGameTests.check(v,m);}
    private static void language(ClientGameTestContext c,String code){var f=c.computeOnClient(m->{m.getLanguageManager().setSelected(code);m.options.languageCode=code;return m.reloadResourcePacks();});c.waitFor(m->f.isDone()&&m.getOverlay()==null);c.waitTicks(5);}
    private static void aim(ClientGameTestContext c,double x,double y,double z){var a=c.computeOnClient(m->{var e=m.player.getEyePosition();double dx=x-e.x,dy=y-e.y,dz=z-e.z;return new float[]{(float)(Math.toDegrees(Math.atan2(dz,dx))-90),(float)-Math.toDegrees(Math.atan2(dy,Math.sqrt(dx*dx+dz*dz)))};});c.getInput().lookAt(a[0],a[1]);c.waitTicks(3);}
    private static void shot(ClientGameTestContext c,String name){c.runOnClient(m->{m.getToastManager().clear();m.gui.getChat().clearMessages(true);});c.getInput().setCursorPos(1,1);c.waitTicks(8);c.takeScreenshot("enchanter-"+name);}
    private static void cursor(ClientGameTestContext c,int x,int y,int width,int height){var a=c.computeOnClient(m->{double s=m.getWindow().getGuiScale();return new double[]{((m.screen.width-width)/2+x)*s,((m.screen.height-height)/2+y)*s};});c.getInput().setCursorPos(a[0],a[1]);c.waitTicks(2);}
    private static void click(ClientGameTestContext c,int x,int y,int width,int height){cursor(c,x,y,width,height);c.getInput().pressMouse(0);c.waitTicks(3);}
    private static void shift(ClientGameTestContext c,int x,int y,int width,int height){cursor(c,x,y,width,height);c.runOnClient(m->{var e=new net.minecraft.client.input.MouseButtonEvent((m.screen.width-width)/2+x,(m.screen.height-height)/2+y,new net.minecraft.client.input.MouseButtonInfo(0,1));m.screen.mouseClicked(e,false);m.screen.mouseReleased(e);});c.waitTicks(3);}
    private static void close(ClientGameTestContext c){c.getInput().pressKey(o->o.keyInventory);c.waitForScreen(null);c.waitTicks(3);}
    private static void stash(ClientGameTestContext c,int first,int width,int height){var point=c.computeOnClient(m->{var menu=m.player.containerMenu;for(int i=first;i<menu.slots.size();i++)if(!menu.getSlot(i).hasItem()){var slot=menu.getSlot(i);return new int[]{slot.x+8,slot.y+8};}throw new AssertionError("free native inventory slot");});click(c,point[0],point[1],width,height);}
    private static void view(ClientGameTestContext c,TestSingleplayerContext w,BlockPos core){w.getServer().runOnServer(s->{s.overworld().setBlockAndUpdate(core.offset(3,1,-4),Blocks.BARRIER.defaultBlockState());s.getPlayerList().getPlayers().getFirst().teleportTo(core.getX()+3.5,core.getY()+2,core.getZ()-3.5);});c.waitTicks(5);aim(c,core.getX()+.5,core.getY()+.2,core.getZ()+.5);}
    private static void openMachine(ClientGameTestContext c,TestSingleplayerContext w,BlockPos core,int k){w.getServer().runOnServer(s->s.getPlayerList().getPlayers().getFirst().teleportTo(core.getX()+.5,-60,-2.5));c.getInput().pressKey(o->o.keyHotbarSlots[7]);c.waitTicks(4);aim(c,core.getX()+.5,core.getY()+.5,.5);c.getInput().pressKey(o->o.keyUse);if(k==0)c.waitForScreen(MachineEnchantmentScreen.class);else if(k==1)c.waitForScreen(ResearchScreen.class);else c.waitForScreen(DisenchantScreen.class);c.waitTicks(5);}
    private static void openMerchant(ClientGameTestContext c,TestSingleplayerContext w,UUID id){var p=w.getServer().computeOnServer(s->{var v=(Villager)s.overworld().getEntity(id);v.setNoAi(true);v.setPos(2.5,-60,7.5);v.setDeltaMovement(Vec3.ZERO);s.getPlayerList().getPlayers().getFirst().teleportTo(2.5,-60,5.5);return v.position();});c.waitTicks(4);aim(c,p.x,p.y+1,p.z);c.runOnClient(m->check(m.hitResult instanceof EntityHitResult h&&h.getEntity().getUUID().equals(id),"native crosshair targets intended villager: "+m.hitResult));c.getInput().pressKey(o->o.keyUse);c.waitForScreen(MerchantScreen.class);w.getServer().runOnServer(s->((Villager)s.overworld().getEntity(id)).setNoAi(false));c.waitFor(m->!((MerchantMenu)m.player.containerMenu).getOffers().isEmpty());c.waitTicks(5);}
    private static void select(ClientGameTestContext c,int index){click(c,45,28+20*index,276,166);}
    private static Map<String,Integer> counts(TestSingleplayerContext w){return w.getServer().computeOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();var stacks=new ArrayList<ItemStack>();for(int i=0;i<p.getInventory().getContainerSize();i++)stacks.add(p.getInventory().getItem(i));if(p.containerMenu instanceof MerchantMenu)for(int i=0;i<2;i++)stacks.add(p.containerMenu.getSlot(i).getItem());stacks.add(p.containerMenu.getCarried());for(var e:s.overworld().getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,new AABB(p.blockPosition()).inflate(16)))stacks.add(e.getItem());var result=new TreeMap<String,Integer>();for(var stack:stacks)if(!stack.isEmpty())result.merge(BuiltInRegistries.ITEM.getKey(stack.getItem()).toString(),stack.getCount(),Integer::sum);return result;});}
    private static String offersSnapshot(net.minecraft.server.MinecraftServer s,UUID id){var copy=((Villager)s.overworld().getEntity(id)).getOffers().copy();for(var offer:copy)offer.resetSpecialPriceDiff();var ops=RegistryOps.create(com.mojang.serialization.JsonOps.INSTANCE,s.registryAccess());return net.minecraft.world.item.trading.MerchantOffers.CODEC.encodeStart(ops,copy).getOrThrow().toString();}
    @Override public void runTest(ClientGameTestContext c){
        c.getInput().resizeWindow(1280,720);language(c,"en_us");TestWorldSave save;UUID villagerId;Map<String,Integer> savedItems;String offers;var machineIds=new ArrayList<UUID>();var report=new StringBuilder();
        var cores=List.of(new BlockPos(0,-59,0),new BlockPos(9,-59,0),new BlockPos(18,-59,0));
        try(var w=c.worldBuilder().create()){
            save=w.getWorldSave();w.getServer().runCommand("time set day");w.getServer().runCommand("weather clear");w.getServer().runCommand("difficulty peaceful");
            w.getServer().runOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();p.setGameMode(GameType.SURVIVAL);p.getInventory().clearContent();p.giveExperiencePoints(3500);});
            for(int kind=0;kind<3;kind++){
                int k=kind,last=k==0?13:k==1?10:1;var core=cores.get(k);
                w.getServer().runOnServer(s->{AutoAssemblyGameTests.frame(s.overworld(),core,k,last);var p=s.getPlayerList().getPlayers().getFirst();check(p.getInventory().getItem(7).isEmpty(),"placement slot initially empty");p.getInventory().setItem(7,new ItemStack(AutoAssemblyGameTests.original(k,last).getBlock().asItem()));});
                c.getInput().pressKey(o->o.keyHotbarSlots[7]);view(c,w,core);shot(c,"0"+k+"-incomplete-frame");
                w.getServer().runOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();if(k==0)p.teleportTo(core.getX()-.5,-58,-.5);else if(k==1)p.teleportTo(core.getX()+.5,-58.0625,.5);else p.teleportTo(core.getX()+.5,-60,-3.5);});c.waitTicks(4);
                if(k==0)aim(c,core.getX()+.5,-59,.5);else if(k==1)aim(c,core.getX()+.5,-59,-.5);else aim(c,core.getX()+.5,-59.5,.001);
                c.runOnClient(m->check(m.hitResult instanceof BlockHitResult,"native placement hits a supporting face"));c.getInput().pressKey(o->o.keyUse);
                c.waitFor(m->m.level.getBlockState(core).is(k==0?DifferentEnchant.PART:k==1?ResearchContent.PART:DisenchantContent.PART));
                machineIds.add(w.getServer().computeOnServer(s->{check(AutoAssemblyGameTests.formed(s.overworld(),core,k),"native last block auto forms "+k);check(s.getPlayerList().getPlayers().getFirst().getInventory().getItem(7).isEmpty(),"native survival placement consumed one last material");return AutoAssemblyGameTests.id(s.overworld(),core,k);}));
                view(c,w,core);shot(c,"1"+k+"-automatically-formed");
                openMachine(c,w,core,k);
                if(k==0){w.getServer().runOnServer(s->{var m=(MachineEnchantmentMenu)s.getPlayerList().getPlayers().getFirst().containerMenu;m.getSlot(0).set(new ItemStack(Items.BOOK));m.getSlot(1).set(new ItemStack(Items.LAPIS_LAZULI,3));m.broadcastChanges();});c.waitFor(m->((MachineEnchantmentMenu)m.player.containerMenu).preview()!=null&&((MachineEnchantmentMenu)m.player.containerMenu).costs[0]>0);click(c,120,43,260,208);w.getServer().runOnServer(s->check(s.getPlayerList().getPlayers().getFirst().containerMenu.getSlot(0).getItem().is(Items.ENCHANTED_BOOK),"auto enchanting machine native paid option"));shot(c,"20-enchanting-operation");}
                else if(k==1){w.getServer().runOnServer(s->{var recipe=ResearchGameTests.find(s.overworld(),r->!r.scroll());ResearchGameTests.fill((ResearchMenu)s.getPlayerList().getPlayers().getFirst().containerMenu,s.overworld(),recipe,1);});c.waitFor(m->m.player.containerMenu.getSlot(3).hasItem());click(c,188,66,230,218);c.waitFor(m->m.player.containerMenu.getCarried().is(Items.ENCHANTED_BOOK));stash(c,4,230,218);shot(c,"21-research-direct-take");}
                else {w.getServer().runOnServer(s->DisenchantGameTests.fill((DisenchantMenu)s.getPlayerList().getPlayers().getFirst().containerMenu,DisenchantGameTests.fixture(s.overworld()),1));click(c,70,84,230,222);c.waitFor(m->m.player.containerMenu.getSlot(2).hasItem());shift(c,194,42,230,222);w.getServer().runOnServer(s->{var m=(DisenchantMenu)s.getPlayerList().getPlayers().getFirst().containerMenu;check(DisenchantGameTests.rank(m.getSlot(0).getItem(),"minecraft:sharpness")==0&&DisenchantGameTests.rank(m.getSlot(0).getItem(),"minecraft:vanishing_curse")==1,"auto disenchanter retains curse");});shot(c,"22-disenchanting-operation");}
                close(c);
            }
            report.append("Native survival last-block placement (controller / inward lectern / lower amethyst block), no crouch or use-to-form. Existing models and actual paid enchanting, direct research and Shift disenchant with curse retention all passed.\n");
            w.getServer().runOnServer(s->{var chestPos=new BlockPos(5,-60,5);s.overworld().setBlockAndUpdate(chestPos,Blocks.CHEST.defaultBlockState());var chest=(net.minecraft.world.level.block.entity.ChestBlockEntity)s.overworld().getBlockEntity(chestPos);var p=s.getPlayerList().getPlayers().getFirst();int out=0;for(int i=0;i<36;i++)if(BookRecycling.validBook(p.getInventory().getItem(i))){chest.setItem(out++,p.getInventory().getItem(i));p.getInventory().setItem(i,ItemStack.EMPTY);}check(out==3,"earned books safely archived in a real chest, separate from twelve recycling fixtures");});
            villagerId=w.getServer().computeOnServer(s->{var l=s.overworld();for(int x=0;x<=4;x++)for(int z=6;z<=11;z++)if(x==0||x==4||z==6||z==11)l.setBlockAndUpdate(new BlockPos(x,-60,z),Blocks.OAK_FENCE.defaultBlockState());l.setBlockAndUpdate(new BlockPos(2,-60,9),Blocks.ENCHANTING_TABLE.defaultBlockState());var v=EntityType.VILLAGER.create(l,EntitySpawnReason.COMMAND);v.setPos(2.5,-60,8);v.setPersistenceRequired();l.addFreshEntity(v);s.getPlayerList().getPlayers().getFirst().teleportTo(2.5,-60,5);return v.getUUID();});
            c.waitTicks(100);c.waitFor(m->m.level.entitiesForRendering().iterator().hasNext());w.getServer().runOnServer(s->check(((Villager)s.overworld().getEntity(villagerId)).getVillagerData().profession().is(EnchanterContent.PROFESSION_KEY),"native unemployed villager claims standalone table"));
            var portrait=w.getServer().computeOnServer(s->{var v=(Villager)s.overworld().getEntity(villagerId);for(int x=1;x<=3;x++)s.overworld().setBlockAndUpdate(new BlockPos(x,-60,6),Blocks.AIR.defaultBlockState());v.setNoAi(true);v.setYRot(180);v.setYHeadRot(180);v.yBodyRot=180;s.getPlayerList().getPlayers().getFirst().teleportTo(v.getX(),v.getY(),v.getZ()-2.5);return v.position();});aim(c,portrait.x,portrait.y+1,portrait.z);shot(c,"30-enchanter-profession-robe");w.getServer().runOnServer(s->((Villager)s.overworld().getEntity(villagerId)).setNoAi(false));
            openMerchant(c,w,villagerId);w.getServer().runOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();check(p.getInventory().add(new ItemStack(Items.EMERALD,64)),"currency fixture fits without overwriting earned items");p.containerMenu.broadcastChanges();});select(c,0);shot(c,"31-novice-bottles");
            for(int i=0;i<5;i++)click(c,228,45,276,166);stash(c,3,276,166);w.getServer().runOnServer(s->check(((Villager)s.overworld().getEntity(villagerId)).getVillagerXp()==10,"five native bottle purchases award career xp"));close(c);c.waitTicks(45);
            w.getServer().runOnServer(s->{var v=(Villager)s.overworld().getEntity(villagerId);check(v.getVillagerData().level()==2,"native career reaches apprentice");var p=s.getPlayerList().getPlayers().getFirst();p.getInventory().add(new ItemStack(Items.ENCHANTED_BOOK));for(var id:List.of("minecraft:sharpness","minecraft:efficiency","minecraft:mending","minecraft:silk_touch","minecraft:vanishing_curse","minecraft:binding_curse","differentenchant:prospectors_echo","differentenchant:trail_stride","differentenchant_tests:probe","minecraft:unbreaking","minecraft:fortune"))p.getInventory().add(EnchanterGameTests.book(s.overworld(),id,id.endsWith("sharpness")?5:1));var multiple=EnchanterGameTests.book(s.overworld(),"minecraft:sharpness",5);DisenchantGameTests.add(s.overworld(),multiple,"minecraft:vanishing_curse",1);p.getInventory().add(multiple);});
            openMerchant(c,w,villagerId);select(c,1);c.waitFor(m->BookRecycling.validBook(m.player.containerMenu.getSlot(0).getItem()));shot(c,"32-apprentice-any-book");
            for(int i=0;i<12;i++){if(i>0)select(c,1);c.waitFor(m->m.player.containerMenu.getSlot(2).hasItem());shift(c,228,45,276,166);int count=i+1;w.getServer().runOnServer(s->check(((Villager)s.overworld().getEntity(villagerId)).getOffers().get(1).getUses()==count,"one real book -> one core, native shift "+count));}
            select(c,1);c.runOnClient(m->check(m.player.containerMenu.getSlot(0).getItem().isEmpty()&&m.player.containerMenu.getSlot(2).getItem().isEmpty(),"empty enchanted book in inventory never autofills or pays a core"));shot(c,"33-recycling-empty-book-rejected");close(c);c.waitTicks(45);
            w.getServer().runOnServer(s->check(((Villager)s.overworld().getEntity(villagerId)).getVillagerData().level()==3,"twelve native book trades unlock journeyman"));
            openMerchant(c,w,villagerId);select(c,2);c.waitFor(m->m.player.containerMenu.getSlot(2).getItem().is(EnchanterContent.CRYSTAL));shot(c,"34-journeyman-crystal");
            click(c,228,45,276,166);stash(c,3,276,166);close(c);
            int crystalSlot=w.getServer().computeOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();int index=-1;for(int i=0;i<36;i++)if(p.getInventory().getItem(i).is(EnchanterContent.CRYSTAL))index=i;check(index>=0,"crystal was actually bought");if(index!=7){var previous=p.getInventory().getItem(7);p.getInventory().setItem(7,p.getInventory().getItem(index));p.getInventory().setItem(index,previous);}return 7;});
            c.getInput().pressKey(o->o.keyHotbarSlots[crystalSlot]);c.waitTicks(4);c.getInput().pressKey(o->o.keyInventory);c.waitForScreen(InventoryScreen.class);var sp=c.computeOnClient(m->{for(var slot:m.player.containerMenu.slots)if(slot.getItem().is(EnchanterContent.CRYSTAL))return new int[]{slot.x+8,slot.y+8};throw new AssertionError("crystal slot");});cursor(c,sp[0],sp[1],176,166);c.waitTicks(8);c.takeScreenshot("enchanter-35-crystal-tooltip-en");
            language(c,"zh_cn");cursor(c,sp[0],sp[1],176,166);c.waitTicks(8);c.takeScreenshot("enchanter-36-crystal-tooltip-zh");c.runOnClient(m->check(net.minecraft.network.chat.Component.translatable("item.differentenchant.condensed_experience_crystal").getString().equals("凝萃经验结晶"),"native Chinese name"));close(c);
            int xp=w.getServer().computeOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();s.overworld().getEntitiesOfClass(ExperienceOrb.class,new AABB(p.blockPosition()).inflate(16)).forEach(Entity::discard);return p.totalExperience;});c.getInput().lookAt(0,-45);c.waitTicks(3);shot(c,"37-crystal-in-hand");c.getInput().pressKey(o->o.keyUse);c.waitTicks(5);w.getServer().runOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();check(p.totalExperience==xp+100&&p.getMainHandItem().isEmpty(),"native single use gives exactly 100 points and consumes one");check(s.overworld().getEntitiesOfClass(ExperienceOrb.class,new AABB(p.blockPosition()).inflate(16)).isEmpty(),"crystal use spawns no experience orb");});shot(c,"38-crystal-used-100-points");
            w.getServer().runOnServer(s->s.getPlayerList().getPlayers().getFirst().setGameMode(GameType.CREATIVE));c.waitTicks(5);c.getInput().pressKey(o->o.keyInventory);c.waitForScreen(CreativeModeInventoryScreen.class);
            var tabPoint=c.computeOnClient(m->{var tab=BuiltInRegistries.CREATIVE_MODE_TAB.getOrThrow(CreativeModeTabs.INGREDIENTS).value();check(tab.getDisplayItems().stream().anyMatch(i->i.is(EnchanterContent.CRYSTAL)),"native ingredients catalogue includes crystal");return new int[]{(tab.isAlignedRight()?195-27*(7-tab.column())+1:27*tab.column())+13,(tab.row()==CreativeModeTab.Row.TOP?-32:136)+16};});
            click(c,tabPoint[0],tabPoint[1],195,136);cursor(c,100,70,195,136);c.getInput().scroll(-100);c.waitTicks(6);
            var creativeSlot=c.computeOnClient(m->{for(var slot:((CreativeModeInventoryScreen)m.screen).getMenu().slots)if(slot.getItem().is(EnchanterContent.CRYSTAL))return new int[]{slot.x+8,slot.y+8};throw new AssertionError("crystal visible at end of ingredients tab");});cursor(c,creativeSlot[0],creativeSlot[1],195,136);c.waitTicks(8);c.takeScreenshot("enchanter-38b-creative-ingredients");close(c);w.getServer().runOnServer(s->s.getPlayerList().getPlayers().getFirst().setGameMode(GameType.SURVIVAL));c.waitTicks(4);
            w.getServer().runOnServer(s->s.getPlayerList().getPlayers().getFirst().getInventory().add(EnchanterGameTests.book(s.overworld(),"minecraft:mending",1)));c.getInput().pressKey(o->o.keyHotbarSlots[7]);openMerchant(c,w,villagerId);select(c,1);c.waitFor(m->BookRecycling.validBook(m.player.containerMenu.getSlot(0).getItem()));shot(c,"39-chinese-merchant-pending-book");
            w.getServer().runOnServer(s->((Villager)s.overworld().getEntity(villagerId)).setNoAi(true));savedItems=counts(w);offers=w.getServer().computeOnServer(s->offersSnapshot(s,villagerId));
            report.append("Natural unemployed villager POI claim; real merchant screen: five bottle purchases -> apprentice, twelve distinct valid vanilla/lost/curse/foreign/multi books consumed for twelve attuned cores -> journeyman. Empty book skipped. One crystal bought for emeralds and used via native hand packet: exactly +100 XP and -1 item, zero XP orbs. Native EN/ZH tooltip screenshots.\n");
        }
        try(var w=save.open()){
            c.waitTicks(8);check(savedItems.equals(counts(w)),"disconnect with pending merchant input returns real items once, never preview");w.getServer().runOnServer(s->{var v=(Villager)s.overworld().getEntity(villagerId);check(v!=null&&v.getVillagerData().profession().is(EnchanterContent.PROFESSION_KEY)&&v.getVillagerData().level()==3,"profession and unlocked rank persist");check(offers.equals(offersSnapshot(s,villagerId))&&v.getVillagerXp()==80,"offer uses, career XP and base costs persist; transient player discount resets normally");v.setNoAi(false);for(int k=0;k<3;k++)check(machineIds.get(k).equals(AutoAssemblyGameTests.id(s.overworld(),cores.get(k),k)),"all three automatic machines keep identity on disk reopen");});
            openMerchant(c,w,villagerId);shot(c,"40-reloaded-enchanter-trades");close(c);report.append("Actual disconnect while a valid unpaid book is in native merchant slot, disk reopening: inventory plus drops unchanged, all offers/uses/rank and three machine identities persisted.\n");
        }
        try{var dir=Path.of("../reports/enchanter");Files.createDirectories(dir);Files.writeString(dir.resolve("client.txt"),report.toString());}catch(Exception e){throw new RuntimeException(e);}
    }
}
